head.script:
scwin.trigger1_onclick = function(e) {
    var options = {};
    options.headerColor = "#46AAFF";
    options.bodyColor = "#5A5AFF";
    options.footerColor = "#3DFF92";
    options.fileName = "excelData.xlsx"; //또는 xlsx 확장자 사용  
    options.type = "1";
    options.rowNumVisible = "true";
    options.rowNumFooterFontSize = "20";
    var infoArr = {};
    gridView1.advancedExcelDownload(options, infoArr);
};
scwin.dbClick = function(id) {
    var el = WebSquare.wUnit.getDomById($p.id + id);
    scwin.fireDbClick(el);
}
scwin.fireDbClick = function(node) {
    if (document.createEventObject) {
        node.fireEvent('ondblclick');
    } else if (document.createEvent) {
        var evt = document.createEvent('MouseEvents');
        evt.initEvent('dblclick', true, false);
        node.dispatchEvent(evt);
    } else if (typeof node.ondblclick == 'function') {
        node.ondblclick();
    }
}
scwin.unitTest = function() {
    //Init test
    WebSquare.wUnit.start();
    //Test step 1. Source 탭에서 col1의 displayMode='value delim Label' 인지 확인한다.-In the Source tab, verify that col1"s displayMode = 'value delim Label'.
    //Verify 1. displayMode='value delim Label'
    //WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById($p.id+'gridView1_cell_0_0').getAttribute('displayMode') == 'value delim label'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Test step 2. 브라우저에서 name1 컬럼의 데이터를 임의로 선택한다.-Select arbitrarily the data of the name1 column in the browser.\
    //Verify 2. (예) 222/222-(Example) 222/222
    WebSquare.wUnit.addCommand("set", "scwin.dbClick($p.id+'gridView1_cell_0_0')");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('G_'+$p.id+'gridView1___selectbox_col1_itemTable_1').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById($p.id+'gridView1_cell_0_0').innerText == '222/222'", "true");
    //Run and Stop test
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    gridView1.setFooterValue(0, "test1");
    //Function unitTest
    //Create by Truong.Luu
    //Create date 22-Jan-2018
    //End untiTest
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
